export const bannerHTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#ffffff\">\n<meta name=\"description\" content=\"Campus2Care live aggregate operating signals\">\n<title>Jarvis · Campus2Care</title>\n<style>\n:root{color-scheme:light;--red:#e30613;--red-dark:#a90d18;--ink:#211f20;--muted:#6c696a;--line:#eadfdd;--wash:#fff8f6;--gold:#f5b4b8;--shadow:0 22px 70px #44151a12}\n*{box-sizing:border-box}\nhtml,body{font-family:Arial,Helvetica,sans-serif;color:var(--ink);margin:0;min-height:0;background:radial-gradient(ellipse at 82% 12%,#e306130d,transparent 32%),linear-gradient(145deg,#fff 8%,#fffaf8 65%,#fff4f0);overflow-x:hidden}\nbody{font-family:Arial,Helvetica,sans-serif;color:var(--ink);margin:0;min-height:0;background:radial-gradient(ellipse at 82% 12%,#e306130d,transparent 32%),linear-gradient(145deg,#fff 8%,#fffaf8 65%,#fff4f0);overflow-x:hidden}\na{color:inherit;text-decoration:none}\n.shell{min-height:0;max-width:1440px;margin:auto;padding:16px clamp(16px,3vw,34px);display:grid;grid-template-rows:auto auto;gap:14px}\n.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px}\n.brand{display:flex;align-items:center;gap:12px;min-width:0}\n.logo-wrap{width:54px;height:54px;display:grid;place-items:center;flex:none;border:1px solid #f0dddd;border-radius:16px;background:#fff;box-shadow:0 8px 24px #7a151208;overflow:hidden}\n.logo-mark{color:var(--red);font-size:15px;font-weight:950;letter-spacing:-.09em}.core:after{content:\"\";width:18%;height:18%;border-radius:50%;background:radial-gradient(circle at 38% 35%,#fff 0,#ffdadd 22%,#e30613 58%,#a90d18 100%);box-shadow:0 0 18px #e30613,0 0 42px #e3061340;animation:breathe 3.5s ease-in-out infinite}\n.brand-copy{display:grid;gap:4px}\n.brand-name{font-size:11px;font-weight:950;letter-spacing:.2em;color:var(--red-dark)}\n.brand-sub{font-size:12px;color:var(--muted)}\n.privacy{display:flex;align-items:center;gap:9px;padding:10px 14px;border:1px solid #edd0ce;border-radius:999px;background:#fff;color:var(--red-dark);font-size:10px;font-weight:900;letter-spacing:.12em;white-space:nowrap}\n.pulse{width:8px;height:8px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px #e3061314;animation:pulse 2.4s ease-in-out infinite}\n.hero{position:relative;isolation:isolate;overflow:hidden;align-self:stretch;display:grid;grid-template-columns:minmax(0,1fr) minmax(180px,28%);align-items:center;gap:clamp(12px,3vw,38px);min-height:0;padding:clamp(22px,3vw,38px);border:1px solid var(--line);border-radius:24px;background:linear-gradient(118deg,#fff 4%,#fff 56%,#fff6f3 100%);box-shadow:var(--shadow)}\n.hero:before{content:\"\";position:absolute;z-index:-1;inset:0 auto 0 0;width:5px;background:linear-gradient(180deg,var(--red),#f29783,var(--red-dark))}\n.hero:after{content:\"\";position:absolute;z-index:-1;inset:0;pointer-events:none;background-image:linear-gradient(#e3061308 1px,transparent 1px),linear-gradient(90deg,#e3061308 1px,transparent 1px);background-size:34px 34px;mask-image:linear-gradient(90deg,transparent 20%,#000 100%)}\n.copy{max-width:720px}\n.eyebrow{display:flex;align-items:center;gap:10px;color:var(--red-dark);font-size:10px;font-weight:950;letter-spacing:.2em;text-transform:uppercase}\n.eyebrow:before{content:\"\";width:26px;height:2px;background:var(--red)}\nh1{max-width:740px;margin:12px 0 10px;font-size:clamp(28px,3.8vw,46px);line-height:1;letter-spacing:-.06em}\n.sub{max-width:590px;margin:0;color:var(--muted);font-size:clamp(14px,1.5vw,17px);line-height:1.65}\n.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}\n.button{display:inline-flex;align-items:center;justify-content:center;gap:11px;min-height:48px;padding:0 17px;border:1px solid var(--line);border-radius:13px;background:#fff;font-size:11px;font-weight:900;letter-spacing:.07em;transition:transform .18s,border-color .18s,box-shadow .18s}\n.button:hover{transform:translateY(-2px);border-color:#e7b8b5;box-shadow:0 9px 22px #551b1714}\n.button.primary{border-color:var(--red);background:linear-gradient(135deg,var(--red),var(--red-dark));color:#fff;box-shadow:0 10px 24px #e3061328}\n.arrow{font-size:16px;line-height:1}\n.next{display:flex;align-items:center;gap:8px;margin-top:14px;color:#5c5555;font-size:11px}\n.next strong{color:var(--ink)}\n.next-icon{display:grid;place-items:center;width:25px;height:25px;border-radius:8px;background:#fff0ed;color:var(--red);font-weight:900}\n.telemetry{margin-top:18px;border:1px solid #f0dedb;border-radius:18px;padding:14px;background:linear-gradient(135deg,#fffdfc,#fff6f4);box-shadow:inset 0 1px #fff}\n.telemetry-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:11px}\n.telemetry-title{display:flex;align-items:center;gap:8px;color:#573b3d;font-size:9px;font-weight:950;letter-spacing:.15em;text-transform:uppercase}\n.telemetry-title:before{content:\"\";width:7px;height:7px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px #e3061310;animation:pulse 2.4s ease-in-out infinite}\n.feed-state{color:#8b7778;font-size:8px;font-weight:850;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}\n.feed-state[data-state=\"live\"]{color:#a90d18}\n.metric-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}\n.metric{position:relative;min-width:0;overflow:hidden;padding:11px 11px 10px;border:1px solid #f0e4e2;border-radius:13px;background:#fff}\n.metric:after{content:\"\";position:absolute;inset:0 auto 0 0;width:2px;background:linear-gradient(180deg,#ed9b9d,var(--red),#f7c3bd);opacity:.75}\n.metric-label{display:block;overflow:hidden;color:#847779;font-size:8px;font-weight:900;letter-spacing:.07em;text-transform:uppercase;white-space:normal;min-height:2.2em;line-height:1.2}\n.metric-value{display:block;margin-top:4px;color:#211f20;font-size:clamp(21px,2.7vw,34px);font-weight:950;line-height:1;letter-spacing:-.06em;font-variant-numeric:tabular-nums}\n.metric-detail{display:block;margin-top:5px;color:#8b7778;font-size:8px;line-height:1.2;white-space:nowrap}\n.metric-track{position:relative;display:block;height:2px;margin-top:9px;overflow:hidden;border-radius:9px;background:#f5e8e6}\n.metric-track:after{content:\"\";position:absolute;inset:0;width:38%;border-radius:inherit;background:linear-gradient(90deg,transparent,#e30613,#ff9a91,transparent);animation:scan 3.2s ease-in-out infinite}\n.metric:nth-child(2) .metric-track:after{animation-delay:.4s}.metric:nth-child(3) .metric-track:after{animation-delay:.8s}.metric:nth-child(4) .metric-track:after{animation-delay:1.2s}\n.telemetry-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:9px;color:#958687;font-size:8px}\n.telemetry-foot strong{color:#745558;font-weight:850}\n.brand-logo{width:100%;height:100%;object-fit:contain;padding:4px}\n.reactor{position:relative;width:min(100%,250px);aspect-ratio:1;margin:auto;display:grid;place-items:center;filter:drop-shadow(0 18px 32px #7b15251a)}\n.orbit,.core,.satellite{position:absolute;border-radius:50%}\n.orbit.outer{inset:2%;border:1px solid #e3061347;box-shadow:inset 0 0 40px #e3061308;animation:turn 34s linear infinite}\n.orbit.outer:before,.orbit.outer:after{content:\"\";position:absolute;inset:8%;border:1px dashed #e3061370;border-radius:50%}\n.orbit.outer:after{inset:18%;border-style:solid;border-color:#e3061338;animation:turn 20s linear infinite reverse}\n.orbit.mid{inset:24%;border:2px solid #e3061378;box-shadow:0 0 0 10px #e306130a,0 0 32px #e3061328;animation:breathe 3.5s ease-in-out infinite}\n.core{inset:34%;display:grid;place-items:center;overflow:hidden;border:1px solid #e7a8a6;background:radial-gradient(circle at 45% 35%,#fff 0,#fffafa 68%,#fff0ed 100%);box-shadow:0 0 26px #e3061330,inset 0 0 15px #e3061310}\n.satellite{width:9px;height:9px;background:var(--gold);box-shadow:0 0 13px var(--gold);top:10%;right:20%;animation:satellite 6s ease-in-out infinite}\n.reactor-label{position:absolute;bottom:2%;display:flex;align-items:center;gap:7px;color:#84393b;font-size:9px;font-weight:950;letter-spacing:.2em;text-transform:uppercase;white-space:nowrap}\n.beacon{width:6px;height:6px;border-radius:50%;background:var(--red);animation:pulse 2.4s infinite}\n.bottom{display:none}\n.status-card{display:flex;align-items:center;gap:12px;min-height:62px;padding:12px 15px;border:1px solid var(--line);border-radius:15px;background:#ffffffd9}\n.status-icon{display:grid;place-items:center;width:34px;height:34px;flex:none;border-radius:10px;background:#fff0ed;color:var(--red);font-size:15px;font-weight:900}\n.status-text{display:grid;gap:4px;min-width:0}\n.status-title{font-size:10px;font-weight:950;letter-spacing:.1em;text-transform:uppercase}\n.status-note{color:var(--muted);font-size:11px;line-height:1.35}\n.foot{display:flex;justify-content:space-between;gap:12px;color:#817a7b;font-size:9px}\n@keyframes turn{to{transform:rotate(360deg)}}\n@keyframes breathe{50%{transform:scale(1.055);box-shadow:0 0 0 14px #e3061307,0 0 42px #e3061340}}\n@keyframes pulse{50%{box-shadow:0 0 0 8px #e3061308}}\n@keyframes satellite{50%{transform:translate(-16px,18px);opacity:.45}}\n@keyframes scan{0%{transform:translateX(-120%);opacity:.15}35%{opacity:.85}100%{transform:translateX(290%);opacity:.1}}\n@media(max-width:760px){.shell{gap:20px}.hero{grid-template-columns:minmax(0,1fr) 180px;min-height:0;padding:22px 20px;gap:8px}.reactor{width:160px}.foot{flex-direction:row}}\n@media(max-width:520px){.shell{padding:8px;gap:8px}.topbar{align-items:center;gap:6px}.logo-wrap{width:34px;height:34px;border-radius:10px}.logo-mark{font-size:12px}.brand-name{font-size:8px;letter-spacing:.04em}.brand-sub{display:none}.privacy{display:none}.hero{grid-template-columns:1fr;min-height:0;padding:14px 10px;gap:4px}.reactor{width:min(110px,31vw);grid-row:1;margin:0 auto 3px}.copy{grid-row:2;min-width:0}h1{font-size:clamp(20px,7vw,38px);line-height:1.02;margin:10px 0 8px;letter-spacing:-.04em}.eyebrow{font-size:8px;letter-spacing:.1em}.sub{font-size:11px;line-height:1.4}.telemetry{margin-top:12px;padding:9px;border-radius:13px}.telemetry-head{margin-bottom:8px}.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.metric{padding:8px 8px 7px;border-radius:10px}.metric-value{font-size:23px}.metric-label{font-size:7px}.metric-detail{font-size:7px}.telemetry-foot{font-size:7px;margin-top:7px}.next{margin-top:8px;font-size:9px}.foot{flex-direction:column}}\n@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}\n.metric-denominator{font-size:.55em;color:var(--muted)}.research-track{display:block;height:4px;background:#f3e5e4;border-radius:8px;overflow:hidden;margin-top:10px}.research-track>span{display:block;height:100%;width:0;background:linear-gradient(90deg,#e30613,#f5a0a6);border-radius:inherit;transition:width .85s ease}.metric-detail{min-height:2.4em;white-space:normal;line-height:1.3}@media(prefers-reduced-motion:reduce){.research-track>span{transition:none}}@media(max-height:400px){\n.shell{padding:8px 12px;gap:8px}.topbar{gap:8px}.logo-wrap{width:32px;height:32px;border-radius:10px}.brand{gap:8px}.brand-name{font-size:9px}.brand-sub{font-size:9px}.privacy{font-size:8px;padding:8px 10px}.hero{padding:14px 18px;border-radius:18px;grid-template-columns:minmax(0,1fr) minmax(80px,16%);gap:12px}.eyebrow{font-size:8px;letter-spacing:.12em}h1{font-size:26px;line-height:1;margin:6px 0}.sub,.next{display:none}.telemetry{margin-top:8px;padding:10px;border-radius:14px}.telemetry-head{margin-bottom:6px;gap:8px}.telemetry-title{font-size:8px}.feed-state{font-size:7px}.metric-grid{gap:6px}.metric{padding:8px;border-radius:10px}.metric-label{font-size:7px;min-height:2.4em}.metric-value{font-size:26px;margin-top:3px}.metric-detail{font-size:8px;line-height:1.3;min-height:2.4em}.metric-track,.research-track{margin-top:6px}.telemetry-foot{margin-top:6px;font-size:7px}.reactor{width:100%;min-width:0}.reactor-label{font-size:7px;letter-spacing:.08em}\n}\n</style>\n</head>\n<body>\n<main class=\"shell\">\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <span class=\"logo-wrap\"><img class=\"brand-logo\" src=\"data:image/png;base64,\" alt=\"Campus2Care logo\"></span>\n      <span class=\"brand-copy\"><span class=\"brand-name\">Campus2Care</span><span class=\"brand-sub\">Leadership operations · Jarvis</span></span>\n    </div>\n    <div class=\"privacy\"><span class=\"pulse\" aria-hidden=\"true\"></span>LIVE OPERATING SIGNALS</div>\n  </header>\n  <section class=\"hero\" aria-labelledby=\"hero-title\">\n    <div class=\"copy\">\n      <div class=\"eyebrow\">President’s workspace · Jarvis</div>\n      <h1 id=\"hero-title\">Clear signals.<br>Work moves forward.</h1>\n      <p class=\"sub\">Your live picture of volunteers, hospital clearance, due tasks and research progress. Open the matching Notion views below to take action.</p>\n      <section class=\"telemetry\" aria-label=\"Live Campus2Care operating counts\" aria-live=\"polite\">\n        <div class=\"telemetry-head\"><span class=\"telemetry-title\">Live HQ signals</span><span class=\"feed-state\" id=\"feed-state\" data-state=\"loading\">Connecting</span></div>\n        <div class=\"metric-grid\">\n          <article class=\"metric\"><span class=\"metric-label\">Total volunteers</span><strong class=\"metric-value\" data-metric=\"totalVolunteers\">—</strong><span class=\"metric-detail\">All pipeline records</span><span class=\"metric-track\" aria-hidden=\"true\"></span></article>\n          <article class=\"metric\"><span class=\"metric-label\">Cleared on site</span><strong class=\"metric-value\" data-metric=\"clearedVolunteers\">—</strong><span class=\"metric-detail\">Hospital-confirmed · active</span><span class=\"metric-track\" aria-hidden=\"true\"></span></article>\n          <article class=\"metric\"><span class=\"metric-label\">Tasks due</span><strong class=\"metric-value\" data-metric=\"dueTasks\">—</strong><span class=\"metric-detail\">Today + overdue · ET</span><span class=\"metric-track\" aria-hidden=\"true\"></span></article>\n          <article class=\"metric\"><span class=\"metric-label\">Research assessments</span><strong class=\"metric-value\"><span data-metric=\"researchCompleted\">—</span><span class=\"metric-denominator\">/<span id=\"research-total\">—</span></span></strong><span class=\"metric-detail\" id=\"research-detail\">Completion status</span><span class=\"research-track\" role=\"progressbar\" aria-label=\"Research assessment completed or submitted\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\"><span id=\"research-progress\"></span></span></article>\n        </div>\n        <div class=\"telemetry-foot\"><span><strong id=\"updated-at\">Waiting for live feed</strong></span><span>Counts only · no volunteer details</span></div>\n      </section>\n      <div class=\"next\"><span class=\"next-icon\" aria-hidden=\"true\">→</span><span><strong>Next:</strong> use the live Notion work views below.</span></div>\n    </div>\n    <div class=\"reactor\" role=\"img\" aria-label=\"Animated Campus2Care control core\">\n      <span class=\"orbit outer\"></span><span class=\"orbit mid\"></span><span class=\"core\"></span><span class=\"satellite\"></span>\n      <span class=\"reactor-label\"><span class=\"beacon\"></span>C2C · Control active</span>\n    </div>\n  </section>\n</main>\n<script id=\"initial-metrics\" type=\"application/json\">__JARVIS_INITIAL_METRICS__</script>\n<script>\n(() => {\n  const endpoint = \"https://www.campus2care.org/api/jarvis/metrics\";\n  const fields = [\"totalVolunteers\", \"clearedVolunteers\", \"dueTasks\"];\n  const status = document.getElementById(\"feed-state\");\n  const updated = document.getElementById(\"updated-at\");\n  const format = new Intl.NumberFormat();\n  const initialMetrics = JSON.parse(document.getElementById(\"initial-metrics\").textContent);\n  const count = n => Number.isSafeInteger(n) && n >= 0;\n  function valid(data) {\n    return data && fields.every(field => count(data[field])) && data.research &&\n      [data.research.completed, data.research.total, data.research.inProgress, data.research.selected, data.research.newSubmitted, data.research.awaitingReview, data.research.awaitingSubmission, data.research.declined].every(count) &&\n      data.research.completed + data.research.inProgress <= data.research.total &&\n      data.research.phase === \"orientation\" && typeof data.updatedAt === \"string\" && Number.isFinite(Date.parse(data.updatedAt));\n  }\n  function animateValue(element, next) {\n    const previous = Number(element.dataset.value || 0);\n    const start = performance.now();\n    const duration = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches ? 1 : 850;\n    function frame(now) {\n      const progress = Math.min(1, (now - start) / duration);\n      const eased = 1 - Math.pow(1 - progress, 3);\n      element.textContent = format.format(Math.round(previous + (next - previous) * eased));\n      if (progress < 1) requestAnimationFrame(frame);\n      else element.dataset.value = String(next);\n    }\n    requestAnimationFrame(frame);\n  }\n  function render(data) {\n    for (const field of fields) animateValue(document.querySelector(`[data-metric=\"${field}\"]`), data[field]);\n    animateValue(document.querySelector('[data-metric=\"researchCompleted\"]'), data.research.completed);\n    document.getElementById(\"research-total\").textContent = format.format(data.research.total);\n    document.getElementById(\"research-detail\").textContent = `${data.research.selected} selected · ${data.research.newSubmitted} submitted · ${data.research.awaitingSubmission} pending`;\n    const percent = data.research.total ? Math.round(100 * data.research.completed / data.research.total) : 0;\n    document.getElementById(\"research-progress\").style.width = `${percent}%`;\n    const track = document.querySelector(\".research-track\");\n    track.setAttribute(\"aria-valuenow\", String(percent));\n    track.setAttribute(\"aria-valuetext\", `${data.research.completed} of ${data.research.total} complete`);\n    status.textContent = \"Live from HQ\";\n    status.dataset.state = \"live\";\n    updated.textContent = `Updated ${new Date(data.updatedAt).toLocaleTimeString([], { hour: \"numeric\", minute: \"2-digit\", timeZone: \"America/New_York\" })} ET`;\n  }\n  async function refresh() {\n    try {\n      const response = await fetch(endpoint, {cache:\"no-store\", credentials:\"omit\", signal:AbortSignal.timeout(20000), headers:{Accept:\"application/json\"}});\n      if (!response.ok) throw new Error(\"Feed unavailable\");\n      const data = await response.json();\n      if (!valid(data)) throw new Error(\"Feed unavailable\");\n      render(data);\n    } catch {\n      status.textContent = \"Feed unavailable\";\n      status.dataset.state = \"offline\";\n      // Retain the last successful timestamp so old values are never labelled live.\n      if (updated.textContent === \"Waiting for live feed\") updated.textContent = \"Live connection pending\";\n    }\n  }\n  if (valid(initialMetrics)) render(initialMetrics);\n  else {status.textContent=\"Feed unavailable\"; updated.textContent=\"Live connection pending\";}\n  window.setInterval(refresh, 300000);\n  document.addEventListener(\"visibilitychange\", () => { if (!document.hidden) refresh(); });\n})();\n</script>\n</body>\n</html>\n";
